@startuml

class Patient {
  + name : string
}

class Family {
  + name : string
}

class Doctor {
  + name : string
}

class Nurse {
  + name : string
}

class Receptionist {
  + name : string
}

class Appointment {
  + date : date
  + time : time
}

class Visit {
  + diagnosis : string
  + treatment : string
}

class Medication {
  + name : string
}

class Prescription {
  + details : string
}

Family "1" -- "*" Patient : contains
Family "1" -- "0..1" Doctor : has primary care physician
Patient "1" -- "*" Appointment : has
Patient "1" -- "*" Visit : undergoes
Appointment "0..1" -- "0..1" Visit : results in
Visit "*" -- "*" Doctor : seen by
Visit "1" -- "*" Medication : prescribes
Visit "1" -- "1" Prescription : includes
Nurse "1" -- "*" Visit : records
Nurse "1" -- "*" Appointment : schedules
Receptionist "1" -- "*" Appointment : schedules
Receptionist "1" -- "*" Patient : registers
Doctor "1" -- "*" Visit : treats
Doctor "1" -- "*" Prescription : prescribes

@enduml

